    38→impl<E: EthSpec> ExecutionRequests<E> {
    39→    /// Returns the encoding according to EIP-7685 to send
    40→    /// to the execution layer over the engine api.
    41→    pub fn get_execution_requests_list(&self) -> Vec<Bytes> {
    42→        let mut requests_list = Vec::new();
    43→        if !self.deposits.is_empty() {
    44→            requests_list.push(Bytes::from_iter(
    45→                [RequestType::Deposit.to_u8()]
    46→                    .into_iter()
    47→                    .chain(self.deposits.as_ssz_bytes()),
    48→            ));
    49→        }
    50→        if !self.withdrawals.is_empty() {
    51→            requests_list.push(Bytes::from_iter(
    52→                [RequestType::Withdrawal.to_u8()]
    53→                    .into_iter()
    54→                    .chain(self.withdrawals.as_ssz_bytes()),
    55→            ));
    56→        }
    57→        if !self.consolidations.is_empty() {
    58→            requests_list.push(Bytes::from_iter(
    59→                [RequestType::Consolidation.to_u8()]
    60→                    .into_iter()
    61→                    .chain(self.consolidations.as_ssz_bytes()),
    62→            ));
    63→        }
    64→        requests_list
    65→    }
    66→
    67→    /// Generate the execution layer `requests_hash` based on EIP-7685.
    68→    ///
    69→    /// `sha256(sha256(requests_0) ++ sha256(requests_1) ++ ...)`
    70→    pub fn requests_hash(&self) -> Hash256 {
    71→        let mut hasher = DynamicContext::new();
    72→
    73→        for request in self.get_execution_requests_list().iter() {
    74→            let mut request_hasher = DynamicContext::new();
    75→            request_hasher.update(request);
    76→            let request_hash = request_hasher.finalize();
    77→
    78→            hasher.update(&request_hash);
    79→        }
    80→
    81→        hasher.finalize().into()
    82→    }
    83→}
