      "code_excerpt": "// PRIMARY: beacon_node/beacon_chain/src/data_column_verification.rs:validate_data_column_sidecar_for_gossip (lines 474-530)\npub fn validate_data_column_sidecar_for_gossip<T: BeaconChainTypes, O: ObservationStrategy>(\n    data_column: Arc<DataColumnSidecar<T::EthSpec>>,\n    subnet: DataColumnSubnetId,\n    chain: &BeaconChain<T>,\n) -> Result<GossipVerifiedDataColumn<T, O>, GossipDataColumnError> {\n    let column_slot = data_column.slot();\n    verify_data_column_sidecar(&data_column)?;                              // step 1: basic sidecar checks\n    verify_index_matches_subnet(&data_column, subnet, &chain.spec)?;       // step 2: subnet match\n    verify_sidecar_not_from_future_slot(chain, column_slot)?;              // step 3: future slot\n    verify_slot_greater_than_latest_finalized_slot(chain, column_slot)?;   // step 4: finality\n    verify_is_unknown_sidecar(chain, &data_column)?;                       // step 5: dedup\n    // step 6: check DA cache\n    if chain.data_availability_checker.is_data_column_cached(&data_column.block_root(), &data_column) {\n        observe_gossip_data_column(&data_column, chain)?;\n        return Err(GossipDataColumnError::PriorKnownUnpublished);\n    }\n    verify_column_inclusion_proof(&data_column)?;                          // step 7: inclusion proof\n    let parent_block = verify_parent_block_and_finalized_descendant(data_column.clone(), chain)?; // step 8\n    verify_slot_higher_than_parent(&parent_block, column_slot)?;           // step 9\n    verify_proposer_and_signature(&data_column, &parent_block, chain)?;    // step 10: proposer sig\n    let kzg = &chain.kzg;\n    let kzg_verified_data_column = verify_kzg_for_data_column(data_column.clone(), kzg)\n        .map_err(|(_, e)| GossipDataColumnError::InvalidKzgProof(e))?;    // step 11: KZG\n    // step 12: observe slashable\n    chain.observed_slashable.write().observe_slashable(..).map_err(..)?;\n    if O::observe() { observe_gossip_data_column(&data_column, chain)?; }  // step 13: observe\n    Ok(GossipVerifiedDataColumn::new(kzg_verified_data_column, ..))\n}"
    },
